 assert result['paid']['committed'] and not result['paid']['provisional'];assert any(e['type']=='save-request' for e in result['outbox']),'Committed save intent missing from snapshot'
 # Reuse the same controller across a new adoption epoch; refused IDs stay consumed.
 accepted=clean(result['model']);ask({'type':'load','archive':archive});ask({'type':'paid-test-context','panel':'agenda'});again=ask({'type':'convene'});pending=next(e['payload'] for e in again['outbox'] if e['type']=='council-event');before=clean(again['model']);ask({'type':'paid-test-deny','value':True})
 refused=p.evaluate('m=>paidAsk(m)',{'type':'choice','eventId':pending['id'],'index':index});assert not refused['ok'],refused
 after=ask({'type':'export'});assert clean(after['model'])==before,'Refusal changed model/RNG'
