 providerArchive=p.evaluate('paidHost.providerSetup()');expectedProvider=p.evaluate("paidHost.provider('school')");ask({'type':'load','archive':providerArchive});ask({'type':'paid-test-context','panel':'community'});provided=ask({'type':'private-provider','providerKind':'school'});assert len(provided['model']['projects'])>len(json.loads(providerArchive)['projects']),'No funded provider created';assert clean(provided['model'])==clean(expectedProvider),'Provider model/RNG differs'
 ask({'type':'load','archive':providerArchive});ask({'type':'paid-test-context','panel':'community'});beforeProvider=ask({'type':'export'});ask({'type':'paid-test-creator-fault','value':True});creatorRefusal=p.evaluate('m=>paidAsk(m)',{'type':'private-provider','providerKind':'school'});assert not creatorRefusal['ok'];afterProvider=ask({'type':'export'});assert clean(afterProvider['model'])==clean(beforeProvider['model']),'Creator refusal retained financial work';ask({'type':'paid-test-creator-fault','value':False});retryProvider=ask({'type':'private-provider','providerKind':'school'});assert clean(retryProvider['model'])==clean(expectedProvider),'Provider recovery differs'
